 async function openBook(book:SpeakingBook,mode:'practice'|'exam'='practice'){
  if(recording||busy)return;
  const until=bookUntil(book);
  if(mode==='practice'&&until){notify('Questions in this book unlock again on '+new Date(until).toLocaleDateString('en-GB')+'.');return}
  setBusy(true);
  try{
   const admitted=await api('begin-session',{kind:'free',day:book.number,mode});
   sessionCreatedAt.current=Date.parse(admitted.startedAt);
   clearPartSession();sessionAttempts.current={};setPracticeResult(null);setActiveBook(book);setBookMode(mode);setExamMode(mode);
   setData((current:any)=>({...current,scheduling:admitted.scheduling}));
   setSession({kind:'free',day:book.number,list:book.questions,sessionId:admitted.sessionId});
   setQindex(0);reset(book.questions[0]);navigate('practice');
  }catch(e){notify((e as Error).message)}finally{setBusy(false)}
 }
 function openMock(number:number,revision=false){const kind=revision?'revision':'weekly';const chosen=content.exams.find(e=>e.kind===kind&&e.number===number);if(chosen)startSession(kind,chosen.day)}
 function partEstimate(partNumber:number):number|null{
  if(!session||!activeBook)return null;
  const partQuestions=session.list.filter(q=>q.part===partNumber);
  if(!partQuestions.length)return null;
  const scores=partQuestions.map(q=>{
    const attempt=data.attempts.find((a:any)=>a.id===sessionAttempts.current[q.id]&&a.reviewed&&a.mime!=='text/plain');
    if(!attempt?.feedback)return null;
    const criteria=['fluency','lexical','grammar','pronunciation'].map(k=>attempt.feedback.criteria?.[k]?.score);
    if(criteria.some(v=>typeof v!=='number'||!Number.isFinite(v)))return null;
    return criteria.reduce((a:number,b:number)=>a+b,0)/4;
  });
  if(scores.some(v=>v===null))return null;
  const mean=(scores as number[]).reduce((a,b)=>a+b,0)/scores.length;
  return Math.max(0,Math.min(9,Math.round(mean*2)/2));
 }

 async function reviewAttempt(){const attempt=data.attempts.find((a:any)=>a.id===attemptId);if(!attempt?.receipt){notify('Record this answer again to use the current progress-only assessment.');return}try{const result=await api('review-attempt',{receipt:attempt.receipt});rememberAttempt({...attempt,receipt:result.receipt,reviewed:1});notify('Feedback reviewed. You can continue to the next question.')}catch(e){notify((e as Error).message)}}
 const sessionReceipts=()=>session?.list.map(q=>partReceipts.current[q.id]).filter(Boolean)||[];
 async function nextQuestion(){
  if(!session||busy||recording)return;
  const current=session.list[qindex];
  if(!current)return;
  const part=current.part;
  const last=session.list.filter(q=>q.part===part).at(-1);
  if(!partReports[part]){
   // Next question works even before the user clicks the separate Save button.
   // Do not discard the recorded audio by resetting the question too early.
   if(!answered(current.id)){
    if(audio&&elapsed>=3){await saveQuestionAndContinue();return}
    notify('Record your answer, then press Next question or Save answer to continue.');
    return;
   }
   if(current.id===last?.id){await assessCompletedPart(part);return}
   const next=session.list.findIndex((q,i)=>i>qindex&&q.part===part&&!answered(q.id));
   if(next>=0){setQindex(next);reset(session.list[next]);return}
   await assessCompletedPart(part);
   return;
  }
  // A completed Part always leads to the next PART, never back to a question
  // within the completed Part (including when reviewing earlier questions).
  const nextPart=session.list.findIndex(q=>q.part>part);
  if(nextPart>=0){
   setQindex(nextPart);reset(session.list[nextPart]);
   if(session.list[nextPart].part===2)setPrep(60);
   notify('Part '+part+' assessment complete. Previous feedback remains available in Completed Part Assessments.');
   return;
  }
  if(![1,2,3].every(p=>partReports[p])){notify('Complete all three speaking parts before the final result.');return}
  if(session.kind==='free'){
   setBusy(true);
   try{
    setPracticeResult(await api('practice-result',{sessionId:session.sessionId,receipts:sessionReceipts(),questionIds:session.list.map(q=>q.id),...(activeBook?{bookNumber:activeBook.number,bookMode}:{})}));
    if(activeBook)await refresh();
    setModal('free-complete');
   }catch(e){setAssessmentError((e as Error).message);notify((e as Error).message)}
   finally{setBusy(false)}
  }else await completeStage();
 }

